"use strict";(self.webpackChunkbodylapse_docs=self.webpackChunkbodylapse_docs||[]).push([[7140],{4819(e){e.exports=JSON.parse('{"tag":{"label":"decision","permalink":"/bodylapse-docs/decisions/tags/decision","allTagsPath":"/bodylapse-docs/decisions/tags","count":10,"items":[{"id":"0001-native-ios-26-swiftui","title":"ADR 0001: Native iOS 26 SwiftUI app","description":"Bodylapse is a native iPhone app in Swift 6 and SwiftUI with iOS 26 as the minimum version.","permalink":"/bodylapse-docs/decisions/0001-native-ios-26-swiftui"},{"id":"0002-swiftdata-cloudkit-no-backend","title":"ADR 0002: SwiftData with CloudKit and no own backend","description":"User data lives in SwiftData on the device and syncs through the user\'s private CloudKit database, with no accounts and no backend of our own for user data.","permalink":"/bodylapse-docs/decisions/0002-swiftdata-cloudkit-no-backend"},{"id":"0003-freemium-subscription","title":"ADR 0003: Freemium subscription","description":"Bodylapse is free for tracking, check-ins and compare, and a subscription (StoreKit 2) unlocks timelapse export, AI meals and 3D.","permalink":"/bodylapse-docs/decisions/0003-freemium-subscription"},{"id":"0004-xcodegen-project","title":"ADR 0004: XcodeGen-generated project","description":"The Xcode project is generated from project.yml by XcodeGen and is not committed.","permalink":"/bodylapse-docs/decisions/0004-xcodegen-project"},{"id":"0005-glass-momentum-six-palettes","title":"ADR 0005: Glass Momentum design language with six palettes","description":"The app uses the Glass Momentum design language in six palettes, all derived from the Plum palette by a generator script.","permalink":"/bodylapse-docs/decisions/0005-glass-momentum-six-palettes"},{"id":"0006-goal-directions","title":"ADR 0006: Goal directions: Lose, Gain, Maintain","description":"The app supports three goal directions, Lose, Gain and Maintain, with direction-neutral wording throughout.","permalink":"/bodylapse-docs/decisions/0006-goal-directions"},{"id":"0007-3d-body-parametric-fit","title":"ADR 0007: 3D body by parametric model fitting, gated by a spike","description":"The optional 3D body is built by fitting a commercially licensed parametric human model to the four angle photos, and is built only if a feasibility spike passes.","permalink":"/bodylapse-docs/decisions/0007-3d-body-parametric-fit"},{"id":"0008-shared-docs-kit","title":"ADR 0008: Shared docs-kit for Bodylapse and LiquidFlashCards","description":"The docs site machinery is a shared private package, docs-kit, that Bodylapse uses first and LiquidFlashCards moves onto later, instead of each app keeping a copy.","permalink":"/bodylapse-docs/decisions/0008-shared-docs-kit"},{"id":"0009-energy-target-mifflin-bounded-paces","title":"ADR 0009: Daily calorie target from Mifflin-St Jeor with bounded paces","description":"The daily calorie target is Mifflin-St Jeor resting burn times an activity multiplier, adjusted by a pace bounded in kg a week and by calorie floors, computed on read and never stored.","permalink":"/bodylapse-docs/decisions/0009-energy-target-mifflin-bounded-paces"},{"id":"README","title":"Decisions","description":"Index of the architecture decision records (ADRs) that shape the app, and when and how to add a new one.","permalink":"/bodylapse-docs/decisions/"}],"unlisted":false}}')}}]);